Record ExcNum := {
  exc_grade : nat;
  exc_l1    : Q;
}.

Definition exc_of {n} (sq : Vector.t Q n) (e : GA_expr n) : ExcNum :=
  {| exc_grade := max_grade_during sq e;
     exc_l1    := max_l1_during sq e |}.

Record EasyCompiler := {
  R : nat -> Type;

  target : forall {n : nat}, R n -> Corner n -> bool;
  compile : forall {n : nat}, R n -> GA_expr n;

  B : nat -> ExcNum;
  d0 : Q;

  compile_correct :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      computes sq (compile (n:=n) r) (target (n:=n) r);

  compile_exc_bound :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      exc_pre (exc_of sq (compile (n:=n) r)) (B (expr_size (compile (n:=n) r)));

  compile_boolish_bound :
    forall {n : nat} (sq : Vector.t Q n) (r : R n),
      trace_boolish_le sq (compile (n:=n) r) d0
}.

Definition dag_exc (sq : Vector.t Q n) {k} (d : GA_dag k) : ExcNum :=
  {| exc_grade := dag_max_grade sq d;
     exc_l1    := dag_max_l1 sq d |}.

Definition dag_trace_boolish_exists_k (sq : Vector.t Q n) {k}
    (d : GA_dag k) (tol : Q) : Prop :=
  exists bound, dag_trace_boolish_k sq d bound tol.

Definition dag_trace_exact_bool (sq : Vector.t Q n) {k}
    (d : GA_dag k) : Prop :=
  dag_trace_boolish_k sq d 1 0.

Definition dag_computes (sq : Vector.t Q n) {k}
    (d : GA_dag k) (root : Fin.t k) (f : Corner n -> bool) : Prop :=
  forall m : Mask n, eval_dag sq d root m == embed f m.

Lemma all_corners_2 :
  all_corners 2 = [Vector.cons _ Pos _ (Vector.cons _ Pos _ (Vector.nil _));
                   Vector.cons _ Pos _ (Vector.cons _ Neg _ (Vector.nil _));
                   Vector.cons _ Neg _ (Vector.cons _ Pos _ (Vector.nil _));
                   Vector.cons _ Neg _ (Vector.cons _ Neg _ (Vector.nil _))].
